inline constexpr uint32_t kFuncCount =
    sizeof(kFuncVA) / sizeof(kFuncVA[0]);

/// 二分查一个地址落在哪个函数里（含函数内部任意偏移）。
/// 返回下标，找不到返回 kFuncCount。
inline uint32_t FuncAt(uint32_t va) {
    uint32_t lo = 0, hi = kFuncCount;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (kFuncVA[mid] <= va) lo = mid + 1; else hi = mid;
    }
    if (lo == 0) return kFuncCount;
    uint32_t i = lo - 1;
    return (va < kFuncVA[i] + kFuncSize[i]) ? i : kFuncCount;
}

/// 是不是函数入口。
inline bool IsFuncEntry(uint32_t va) {
    uint32_t i = FuncAt(va);
    return i < kFuncCount && kFuncVA[i] == va;
}

